	inputLen := len(req.InputTokens)
	isSession := req.SessionID != ""

	for _, snap := range snapshots {
		el := float64(snap.EffectiveLoad())

		// 1. Under high load, aggressively penalize overloaded instances
		if avgLoad > 2.0 && el > avgLoad*1.3 {
